import argparse,base64,json
from pathlib import Path
from driver import ps
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('language',choices=['ko','en']);a=p.parse_args();assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='home'
owned="$A=[System.Windows.Automation.AutomationElement];$T=[System.Windows.Automation.TreeScope];$w=@($A::RootElement.FindAll($T::Children,[System.Windows.Automation.Condition]::TrueCondition)|Where-Object{$_.Current.Name.StartsWith('WelcomeEntryHint preview · original isolation')-and(Get-Process -Id $_.Current.ProcessId).Path.EndsWith('\\Microsoft\\Edge\\Application\\msedge.exe')});"
print(ps(owned+"if($w.Count){throw 'Owned preview already open'};Start-Process msedge.exe -ArgumentList @('--new-window','http://10.211.55.2:8768/welcomeentryhint-preview.html?language="+a.language+"&width=438');"))
code=owned+"$deadline=[DateTime]::UtcNow.AddSeconds(8);do{if($w.Count-eq1){break};Start-Sleep -Milliseconds 50;"+owned+"}while([DateTime]::UtcNow-lt$deadline);if($w.Count-ne1){throw 'Owned preview missing'};$w=$w[0];Add-Type 'using System;using System.Runtime.InteropServices;public static class HintCaptureGuard{[DllImport(\"user32.dll\")]public static extern IntPtr GetForegroundWindow();}';if([HintCaptureGuard]::GetForegroundWindow().ToInt64()-ne$w.Current.NativeWindowHandle){throw 'Owned foreground required'};$r=$w.Current.BoundingRectangle;if($r.Width-lt500-or$r.Width-gt4000-or$r.Height-lt400-or$r.Height-gt2400){throw 'Wrong preview bounds'};Add-Type -AssemblyName System.Drawing;$bmp=[Drawing.Bitmap]::new([int]$r.Width,[int]$r.Height);$g=[Drawing.Graphics]::FromImage($bmp);$g.CopyFromScreen([int]$r.Left,[int]$r.Top,0,0,$bmp.Size);$ms=[IO.MemoryStream]::new();$bmp.Save($ms,[Drawing.Imaging.ImageFormat]::Png);[Console]::WriteLine([Convert]::ToBase64String($ms.ToArray()));$g.Dispose();$bmp.Dispose();$ms.Dispose();"
try:
 expected='저장한 결과 JSON은 DB 연결이나 새 검사 없이 바로 열어 확인할 수 있습니다.' if a.language=='ko' else 'Open a saved result JSON without connecting to a DB or running a new check.'
 peer=owned+"$deadline=[DateTime]::UtcNow.AddSeconds(8);do{if($w.Count-eq1){break};Start-Sleep -Milliseconds 50;"+owned+"}while([DateTime]::UtcNow-lt$deadline);if($w.Count-ne1){throw 'Owned source peer window missing'};$name='"+expected+"';$texts=$w[0].FindAll($T::Descendants,[System.Windows.Automation.AndCondition]::new([System.Windows.Automation.PropertyCondition]::new($A::ControlTypeProperty,[System.Windows.Automation.ControlType]::Text),[System.Windows.Automation.PropertyCondition]::new($A::NameProperty,$name)));if($texts.Count-ne1){throw 'Original single text peer required'};[pscustomobject]@{textPeerCount=$texts.Count;name=$texts[0].Current.Name;type=$texts[0].Current.ControlType.ProgrammaticName}|ConvertTo-Json"
 (r/f'docs/replica/source/welcomeentryhint-windows-source-{a.language}-peer.json').write_text(ps(peer)+'\n')
 target=r/f'docs/replica/source/welcomeentryhint-windows-source-{a.language}-438.png';target.write_bytes(base64.b64decode(ps(code)));print(target)
finally:print(ps(owned+"if($w.Count-eq1){$w[0].GetCurrentPattern([System.Windows.Automation.WindowPattern]::Pattern).Close()}elseif($w.Count){throw 'Cleanup unique required'};"))
